def parse_rows(blob,n):
    rows={}
    for line in blob.splitlines():
        if not line.strip():continue
        vals=[s.strip() for s in line.split('|')]
        if len(vals)!=n:raise ValueError((len(vals),line))
        if vals[0] in rows:raise ValueError('Duplicado '+vals[0])
        rows[vals[0]]=vals
    return rows
